<?php
declare(strict_types=1);
require __DIR__.'/team-recognition.php';
use App\Services\{ClinicalReturnService,NursingWorklistService,CareService,Crypto};
$patient=$s->insert('patients',['company_id'=>1,'name'=>'Retorno médico fictício']);
$s->insert('care_team_assignments',['company_id'=>1,'patient_id'=>$patient,'team_id'=>1]);
$doctorReturn=new ClinicalReturnService(new CareService($s,$doctor));
$nurseReturn=new ClinicalReturnService(new CareService($s,$nurse));
$queue=new NursingWorklistService(new CareService($s,$nurse));
$assessment=date('Y-m-d',time()-30*86400);$yesterday=date('Y-m-d',time()-86400);
$input=['risk'=>3,'due_date'=>$yesterday,'assessment_date'=>$assessment,'team_id'=>1,'version'=>0];
verify($doctorReturn->view($patient)===['available'=>false,'version'=>0],'No risk inferred without doctor confirmation');
foreach([$manager,$admin,$worker,$dependent,$navigator] as $actor) {
    denied(fn()=>(new ClinicalReturnService(new CareService($s,$actor)))->view($patient),403);
    denied(fn()=>(new ClinicalReturnService(new CareService($s,$actor)))->save($patient,$input),403);
}
denied(fn()=>$nurseReturn->save($patient,$input),403);
denied(fn()=>$doctorReturn->save(3,$input),404);
foreach([['risk'=>5],['risk'=>0],['risk'=>'3'],['version'=>null],['due_date'=>'2026-02-30'],['due_date'=>$assessment],['assessment_date'=>date('Y-m-d',time()+86400)]] as $invalid) denied(fn()=>$doctorReturn->save($patient,array_replace($input,$invalid)),422);
$confirmed=$doctorReturn->save($patient,$input);
verify($confirmed['risk']===3 && $confirmed['version']===1 && $confirmed['status']==='overdue','Doctor confirms known risk and date with version');
verify($nurseReturn->view($patient)['risk']===3,'Nurse can consult confirmed risk');
$raw=$s->one('SELECT * FROM clinical_return_plans WHERE patient_id=?',[$patient]);
verify($raw['risk_cipher']!=='3' && Crypto::decrypt($raw['risk_cipher'])==='3','Risk is encrypted at rest');
verify($confirmed['history'][0]['payload']['after']['risk']===3,'History retains confirmed values and author');
denied(fn()=>$doctorReturn->save($patient,$input),409);
denied(fn()=>$doctorReturn->save($patient,array_replace($input,['version'=>1,'risk'=>2])),422);
$confirmed=$doctorReturn->save($patient,array_replace($input,['version'=>1,'risk'=>2,'reason'=>'Reavaliação médica fictícia documentada.']));
verify($confirmed['history'][0]['event_type']==='risk_downgraded' && $confirmed['history'][0]['payload']['before']['risk']===3,'Downgrade requires reason and preserves previous risk');
$queue->sync();$getItem=function()use($queue,$patient){foreach($queue->queue(['status'=>'all'])['items'] as $row)if((int)$row['patient_id']===$patient && $row['source_type']==='clinical_return')return $row;throw new RuntimeException('Missing automatic return');};
$item=$getItem();
verify($item['overdue'] && str_contains($item['priority_reason'],'administrativa'),'Overdue return joins queue without clinical risk prioritization');
$queue->sync();verify((int)$s->one('SELECT COUNT(*) n FROM care_pending_items WHERE source_type=? AND patient_id=?',['clinical_return',$patient])['n']===1,'Sync is idempotent');
denied(fn()=>$queue->action((int)$item['id'],['type'=>'resolve','version'=>(int)$item['version'],'note'=>'Não substitui atendimento.']),422);
$queue->action((int)$item['id'],['type'=>'contact','version'=>(int)$item['version'],'channel'=>'phone','outcome'=>'no_answer','note'=>'Tentativa fictícia sem resposta.']);
verify((bool)array_filter($queue->queue(['contact_state'=>'lost'])['items'],fn($r)=>(int)$r['id']===(int)$item['id']),'Contact lost filter uses documented attempt');
$item=$getItem();$queue->action((int)$item['id'],['type'=>'contact','version'=>(int)$item['version'],'channel'=>'phone','outcome'=>'reached','note'=>'Contato retomado.']);
verify(!array_filter($queue->queue(['contact_state'=>'lost'])['items'],fn($r)=>(int)$r['id']===(int)$item['id']),'Successful later contact leaves lost filter');
$s->insert('appointments',['company_id'=>1,'patient_id'=>$patient,'professional_id'=>1,'scheduled_at'=>$assessment.' 12:00:00','status'=>'attended']);
$s->insert('appointments',['company_id'=>1,'patient_id'=>$patient,'professional_id'=>$nurse['id'],'scheduled_at'=>$yesterday.' 10:00:00','status'=>'attended']);
$future=$s->insert('appointments',['company_id'=>1,'patient_id'=>$patient,'professional_id'=>1,'scheduled_at'=>date('Y-m-d H:i:s',time()+86400),'status'=>'attended']);
verify($doctorReturn->view($patient)['attendance']===null,'Same assessment day, nurse consultation and future status cannot complete medical return');
$item=$getItem();denied(fn()=>$queue->action((int)$item['id'],['type'=>'record_return','version'=>(int)$item['version'],'appointment_id'=>$future]),422);
$visit=$s->insert('appointments',['company_id'=>1,'patient_id'=>$patient,'professional_id'=>1,'scheduled_at'=>$yesterday.' 12:00:00','status'=>'confirmed']);
verify($doctorReturn->view($patient)['attendance']===null,'Booking and confirmation alone do not complete return');
$item=$getItem();$queue->action((int)$item['id'],['type'=>'record_return','version'=>(int)$item['version'],'appointment_id'=>$visit]);
$queue->sync();
verify($doctorReturn->view($patient)['status']==='completed' && $getItem()['status']==='resolved','Nurse records actual attendance and automatic return leaves active queue');
$s->execute('UPDATE appointments SET status=? WHERE id=?',['cancelled',$visit]);$queue->sync();
verify($getItem()['status']==='open','Corrected attendance reopens the due return');
$item=$getItem();$scheduled=$queue->action((int)$item['id'],['type'=>'schedule_return','version'=>(int)$item['version'],'team_id'=>1,'professional_id'=>1,'date'=>date('Y-m-d',time()+3*86400),'time'=>'13:41']);
verify($getItem()['status']==='in_progress' && $doctorReturn->view($patient)['attendance']===null,'Scheduling from sheet does not complete clinical return');
denied(fn()=>$queue->action((int)$item['id'],['type'=>'schedule_return','version'=>(int)$item['version'],'team_id'=>1,'professional_id'=>1,'date'=>date('Y-m-d',time()+3*86400),'time'=>'13:42']),409);
$confirmed=$doctorReturn->save($patient,array_replace($input,['version'=>2,'risk'=>2,'due_date'=>date('Y-m-d')]));
$queue->sync();verify((bool)array_filter($queue->queue(['deadline'=>'today'])['items'],fn($r)=>(int)$r['id']===(int)$item['id']),'Due today filter includes confirmed return');
$confirmed=$doctorReturn->save($patient,array_replace($input,['version'=>3,'risk'=>2,'due_date'=>date('Y-m-d',time()+40*86400)]));
$queue->sync();verify($getItem()['status']==='resolved','Future revision outside seven-day window leaves current queue');
$confirmed=$doctorReturn->save($patient,array_replace($input,['version'=>4,'risk'=>2]));$queue->sync();verify($getItem()['status']==='open','Revision returning to due window reopens same tracked item');
$s->execute('UPDATE care_team_assignments SET active=0 WHERE patient_id=?',[$patient]);
denied(fn()=>$doctorReturn->view($patient),404);
verify(!array_filter($queue->queue()['items'],fn($r)=>(int)$r['patient_id']===$patient),'Revoked patient disappears from queue');
echo "OK: {$count} combined clinical return/domain checks\n";
